// La IA juzga, el código valida: reglas de negocio que el Juez no puede saltear
const v = $input.item.json.output;
const criticidad = $('When Executed by Another Workflow').item.json.criticidad;
const umbral = criticidad === 'alta' ? 5 : 4;   // precios, pagos o reembolsos exigen 5
let estado = v.estado_veredicto;

// Si falta la pregunta o la respuesta, nunca se aprueba: el Juez no tuvo qué evaluar
const entrada = $('When Executed by Another Workflow').item.json;
const sinDatos = !entrada.pregunta || !entrada.respuesta_agente || entrada.respuesta_agente === 'undefined';
if (sinDatos) {
  return { json: {
    exactitud_factual: 1,
    estado_veredicto: 'RECHAZADO',
    veredicto_juez: v.estado_veredicto,
    categoria_error: 'ENTRADA_INVALIDA',
    errores: ['El Juez no recibió la pregunta o la respuesta a evaluar.'],
    justificacion: 'Validación determinista: sin datos de entrada no se puede aprobar.',
    umbral_aplicado: umbral
  }};
}

if (v.categoria_error === 'SEGURIDAD' || v.exactitud_factual <= 2) estado = 'RECHAZADO';
else if (estado === 'ACEPTADO' && v.exactitud_factual < umbral) estado = 'CORREGIR';

return { json: {
  exactitud_factual: v.exactitud_factual,
  estado_veredicto: estado,
  veredicto_juez: v.estado_veredicto,
  categoria_error: v.categoria_error,
  errores: v.errores,
  justificacion: v.justificacion,
  umbral_aplicado: umbral
}};
